package slicer

import (
	"strings"
	"testing"
)

const footer = `; HEADER_BLOCK_START
; generated by OrcaSlicer 2.4.2
; total layer number: 100
; max_z_height: 20.00
; HEADER_BLOCK_END
G1 X1 Y1
; estimated first layer printing time (normal mode) = 0.73s
; filament used [mm] = 2345.22
; filament used [cm3] = 5.64
; filament used [g] = 7.16
; total filament used [g] = 7.16
; total layers count = 100
; estimated printing time (normal mode) = 21m 57s
`

func TestParseGcode(t *testing.T) {
	st, err := ParseGcode(strings.NewReader(footer))
	if err != nil {
		t.Fatal(err)
	}
	if st.Seconds != 1317 || st.FilamentMM != 2345.22 || st.FilamentG != 7.16 || st.Layers != 100 || st.MaxZ != 20 {
		t.Fatalf("stats = %+v", st)
	}
}

func TestParseGcodeHours(t *testing.T) {
	st, err := ParseGcode(strings.NewReader("; filament used [mm] = 1\n; total filament used [g] = 2\n; estimated printing time (normal mode) = 2h 3m 4s\n"))
	if err != nil {
		t.Fatal(err)
	}
	if st.Seconds != 7384 {
		t.Fatalf("seconds = %d, want 7384", st.Seconds)
	}
}

func TestParseGcodeNoFooter(t *testing.T) {
	if _, err := ParseGcode(strings.NewReader("G28\nG1 X1\n")); err == nil {
		t.Fatal("expected an error without statistics")
	}
}

func TestGcodeName(t *testing.T) {
	got := gcodeName("Xmas light case", "PETG", 0.2, 44*60+45)
	if got != "xmas-light-case_PETG_0.20_44m45s.gcode" {
		t.Fatalf("name = %q", got)
	}
	if got := DurationLabel(3723); got != "1h02m" {
		t.Fatalf("label = %q", got)
	}
}
